#!/usr/bin/env node
'use strict';

/**
 * Generates THIRD_PARTY_NOTICES.md from the `source` / `license` frontmatter of every vendored
 * skill in skills_library/ and the license files that ship next to them.
 *
 * Usage: node .github/scripts/third-party-notices.js [--check]
 *   --check  exit 1 when the committed file is out of date (nothing is written)
 */

const fs = require('node:fs');
const path = require('node:path');

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const LIBRARY_DIR = path.join(REPO_ROOT, 'skills_library');
const OUTPUT_FILE = path.join(REPO_ROOT, 'THIRD_PARTY_NOTICES.md');
const APACHE_TEXT_FILE = 'skills_library/LICENSE-APACHE-2.0.txt';
const LICENSE_FILE_PATTERN = /^(LICENSE|LICENCE|COPYING)(\.[a-z]+)?$/i;
const FRONTMATTER_PATTERN = /^---\r?\n([\s\S]*?)\r?\n---/;
const UNKNOWN = 'not declared';

function readFrontmatter(skillFile) {
  let text;
  try {
    text = fs.readFileSync(skillFile, 'utf8');
  } catch (error) {
    if (error && error.code === 'ENOENT') return {};
    throw error;
  }
  const match = FRONTMATTER_PATTERN.exec(text.replace(/^﻿/, ''));
  if (!match) return {};
  const fields = {};
  for (const line of match[1].split(/\r?\n/)) {
    const field = /^(source|license):\s*(.*)$/.exec(line);
    if (field) fields[field[1]] = field[2].trim().replace(/^["']|["']$/g, '');
  }
  return fields;
}

function escapeCell(text) {
  return String(text).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
}

function collectSkills() {
  return fs.readdirSync(LIBRARY_DIR, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b))
    .map((name) => {
      const dir = path.join(LIBRARY_DIR, name);
      const { source, license } = readFrontmatter(path.join(dir, 'SKILL.md'));
      const licenseFile = fs.readdirSync(dir).find((file) => LICENSE_FILE_PATTERN.test(file)) || null;
      return { name, source: source || UNKNOWN, license: license || UNKNOWN, licenseFile };
    });
}

/** One row per declared upstream source: how many skills come from it and which licenses they declare. */
function renderSourceSummary(skills) {
  const bySource = new Map();
  for (const skill of skills) {
    const entry = bySource.get(skill.source) || { count: 0, licenses: new Set() };
    entry.count += 1;
    entry.licenses.add(skill.license);
    bySource.set(skill.source, entry);
  }
  const rows = [...bySource.entries()].sort((a, b) => b[1].count - a[1].count || a[0].localeCompare(b[0]));
  const lines = [
    '## Upstream sources',
    '',
    '| Declared source | Skills | Declared licenses |',
    '| --------------- | -----: | ----------------- |',
  ];
  for (const [source, { count, licenses }] of rows) {
    const licenseList = [...licenses].sort((a, b) => a.localeCompare(b)).map(escapeCell).join(', ');
    lines.push(`| ${escapeCell(source)} | ${count} | ${licenseList} |`);
  }
  lines.push('', '## Skills', '');
  return lines;
}

function render(skills) {
  const apache = skills.filter((s) => /apache/i.test(`${s.source} ${s.license}`));
  const unknown = skills.filter((s) => /^unknown\b|complete terms in license\.txt/i.test(s.license) && !s.licenseFile);
  const lines = [
    '# Third-Party Notices',
    '',
    '<!-- Generated by `node .github/scripts/third-party-notices.js`. Do not edit by hand. -->',
    '',
    'The MIT license in `LICENSE` covers the original BoomOpen Workflow Kit code and documents',
    '(`cli/`, `rules/`, `commands/`, `agents/`, `platforms/`, `matrix-skills/`, `scripts/`, `skills/`,',
    '`documents/`, `web/` and the root Markdown files).',
    '',
    '`skills_library/` is a vault of community and third-party skills. Each skill keeps the license of',
    'its upstream project; it is **not** relicensed under MIT. The table below lists, for every skill,',
    'the `source` and `license` its `SKILL.md` declares and the license file that ships with it.',
    '',
    `- Skills that declare Apache License 2.0 without their own copy of the license text are covered by`,
    `  the copy in \`${APACHE_TEXT_FILE}\` (${apache.length} skills declare Apache 2.0).`,
    '- "community", "personal", "self" and "original" are the labels used by the upstream skill',
    '  collections; they do not name a license.',
    `- ${unknown.length} skills declare an unknown license or point to a license file that was not vendored`,
    '  (listed below with "⚠️"). Verify their upstream terms before redistributing them.',
    '- Before running a skill\'s scripts, review them: they are third-party code.',
    '',
    ...renderSourceSummary(skills),
    '| Skill | Declared source | Declared license | License file |',
    '| ----- | --------------- | ---------------- | ------------ |',
  ];
  for (const skill of skills) {
    const flag = unknown.includes(skill) ? '⚠️ ' : '';
    const file = skill.licenseFile ? `\`${skill.name}/${skill.licenseFile}\`` : '—';
    lines.push(`| \`${skill.name}\` | ${escapeCell(skill.source)} | ${flag}${escapeCell(skill.license)} | ${file} |`);
  }
  lines.push('');
  return lines.join('\n');
}

function main() {
  const output = render(collectSkills());
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = fs.readFileSync(OUTPUT_FILE, 'utf8');
    } catch (error) {
      if (!error || error.code !== 'ENOENT') throw error;
    }
    if (current.replace(/\r\n/g, '\n') !== output) {
      console.error('THIRD_PARTY_NOTICES.md is out of date. Run: node .github/scripts/third-party-notices.js');
      return 1;
    }
    console.log('THIRD_PARTY_NOTICES.md is up to date.');
    return 0;
  }
  fs.writeFileSync(OUTPUT_FILE, output, 'utf8');
  console.log(`Wrote ${path.relative(REPO_ROOT, OUTPUT_FILE)}`);
  return 0;
}

process.exitCode = main();
